#!/usr/bin/env node
/**
 * Validates that env values match expected formats.
 * Prints ONLY pass/fail per variable — never the secret values themselves.
 *
 * Usage: node scripts/check-env-format.js [path-to-env-file]
 */
const fs = require('fs');

const envPath = process.argv[2] || '.env.test';

// name -> regex describing the expected shape (not the real value)
const RULES = {
  DATABASE_URL:          /^postgres(ql)?:\/\/.+:.+@.+:\d+\/.+$/,
  AWS_ACCESS_KEY_ID:     /^AKIA[0-9A-Z]{12,}$/,
  AWS_SECRET_ACCESS_KEY: /^.{20,}$/,           // length-only; don't assert structure
  ANTHROPIC_API_KEY:     /^sk-ant-.+$/,
  STRIPE_SECRET_KEY:     /^sk_(live|test)_.+$/,
  LOGFIRE_TOKEN:         /^.{8,}$/,            // length-only
};

function parseEnv(text) {
  const out = {};
  for (const line of text.split('\n')) {
    const t = line.trim();
    if (!t || t.startsWith('#')) continue;
    const i = t.indexOf('=');
    if (i === -1) continue;
    out[t.slice(0, i).trim()] = t.slice(i + 1).trim();
  }
  return out;
}

let text;
try {
  text = fs.readFileSync(envPath, 'utf8');
} catch (e) {
  console.error(`Could not read ${envPath}: ${e.message}`);
  process.exit(1);
}

const env = parseEnv(text);
let allOk = true;

for (const [name, rule] of Object.entries(RULES)) {
  const present = Object.prototype.hasOwnProperty.call(env, name);
  const ok = present && rule.test(env[name]);
  if (!ok) allOk = false;
  // Output never includes env[name] — only the variable name and a verdict.
  console.log(`${ok ? '✅' : '❌'} ${name}${present ? '' : ' (missing)'}`);
}

console.log(allOk ? '\nAll variables match expected formats.' : '\nSome variables failed format validation.');
process.exit(allOk ? 0 : 1);

